CREATE TYPE "member_role" AS ENUM ('owner','admin','team_lead','agent','viewer');
CREATE TYPE "conversation_status" AS ENUM ('open','waiting','closed','archived','spam');
CREATE TYPE "message_direction" AS ENUM ('inbound','outbound');
CREATE TYPE "message_status" AS ENUM ('pending','sent','delivered','read','failed');

CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "email" text NOT NULL, "password_hash" text NOT NULL, "full_name" text NOT NULL, "is_active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "users_email_uq" ON "users" ("email");
CREATE TABLE "organizations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "slug" text NOT NULL, "timezone" text NOT NULL DEFAULT 'Europe/Istanbul', "default_locale" text NOT NULL DEFAULT 'tr', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "organizations_slug_uq" ON "organizations" ("slug");
CREATE TABLE "organization_members" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "role" member_role NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "organization_members_org_user_uq" ON "organization_members" ("organization_id","user_id");
CREATE TABLE "teams" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "name" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "channels" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "name" text NOT NULL, "provider" text NOT NULL, "phone_number" text NOT NULL, "status" text NOT NULL DEFAULT 'connected', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "contacts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "first_name" text NOT NULL, "last_name" text, "normalized_phone" text NOT NULL, "email" text, "custom_fields" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "contacts_org_phone_uq" ON "contacts" ("organization_id","normalized_phone");
CREATE TABLE "conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "contact_id" uuid NOT NULL REFERENCES "contacts"("id"), "channel_id" uuid NOT NULL REFERENCES "channels"("id"), "assignee_id" uuid REFERENCES "users"("id"), "status" conversation_status NOT NULL DEFAULT 'open', "priority" text NOT NULL DEFAULT 'normal', "stage" text NOT NULL DEFAULT 'Yeni Lead', "unread_count" integer NOT NULL DEFAULT 0, "last_message_at" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "conversations_org_status_idx" ON "conversations" ("organization_id","status");
CREATE INDEX "conversations_org_assignee_idx" ON "conversations" ("organization_id","assignee_id");
CREATE INDEX "conversations_last_message_idx" ON "conversations" ("organization_id","last_message_at");
CREATE TABLE "messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "conversation_id" uuid NOT NULL REFERENCES "conversations"("id") ON DELETE CASCADE, "client_message_id" uuid, "provider_message_id" text, "direction" message_direction NOT NULL, "status" message_status NOT NULL DEFAULT 'pending', "body" text NOT NULL, "sender_id" uuid REFERENCES "users"("id"), "sent_at" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "messages_org_client_id_uq" ON "messages" ("organization_id","client_message_id");
CREATE UNIQUE INDEX "messages_provider_id_uq" ON "messages" ("provider_message_id");
CREATE TABLE "outbox_jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "kind" text NOT NULL, "aggregate_id" uuid NOT NULL, "payload" jsonb NOT NULL, "status" text NOT NULL DEFAULT 'pending', "attempts" integer NOT NULL DEFAULT 0, "next_attempt_at" timestamptz NOT NULL DEFAULT now(), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "outbox_status_attempt_idx" ON "outbox_jobs" ("status","next_attempt_at");
CREATE TABLE "audit_logs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "actor_id" uuid REFERENCES "users"("id"), "action" text NOT NULL, "entity_type" text NOT NULL, "entity_id" uuid, "metadata" jsonb NOT NULL DEFAULT '{}', "created_at" timestamptz NOT NULL DEFAULT now());
